package catalog

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"testing"

	"github.com/ditto-assistant/dittobench-datagen/protocol"
)

// The hand-maintained catalog mirrors live elsewhere in the monorepo and are
// regenerated by cmd/catalogmirror. These tests read them back and compare the
// tool-name sequence to CatalogForVersion(13) so a change to the Go catalog
// that forgets a mirror fails here. Each skips when its mirror is absent (the
// module is also consumed standalone).
var mirrorRoot = filepath.Join("..", "..", "..")

func readMirror(t *testing.T, rel string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(mirrorRoot, rel))
	if err != nil {
		t.Skipf("mirror %s not present: %v", rel, err)
	}
	return string(raw)
}

func TestStarterKitCatalogMirrorMatchesV13Surface(t *testing.T) {
	src := readMirror(t, "miners/dittobench-starter-kit/src/catalog.rs")
	body := src[:regexp.MustCompile(`#\[cfg\(test\)\]`).FindStringIndex(src)[0]]
	var names []string
	for _, m := range regexp.MustCompile(`(?m)^\s*tool\(\s*\n?\s*"([a-z_]+)"`).FindAllStringSubmatch(body, -1) {
		names = append(names, m[1])
	}
	if want := ProductionToolNames(protocol.BenchVersionV13); !reflect.DeepEqual(names, want) {
		t.Fatalf("starter-kit catalog.rs drifted from CatalogForVersion(13):\n got %v\nwant %v\nregenerate with: go run ./cmd/catalogmirror -bench-version 13 -format rust", names, want)
	}
	for _, enum := range []string{`SchemaType::Enum(&["system", "light", "dark", "midnight", "solarized"])`, `SchemaType::Enum(&["low", "medium", "high"])`} {
		if !regexp.MustCompile(regexp.QuoteMeta(enum)).MatchString(body) {
			t.Errorf("starter-kit catalog.rs lacks %s", enum)
		}
	}
}

func TestScreenerOracleToolNamesMatchV13Surface(t *testing.T) {
	src := readMirror(t, "workers/screener/ditto_screener/policy.py")
	block := regexp.MustCompile(`(?s)_ORACLE_TOOL_NAMES: tuple\[str, \.\.\.\] = \((.*?)\n\)`).FindStringSubmatch(src)
	if block == nil {
		t.Fatal("_ORACLE_TOOL_NAMES block not found")
	}
	var names []string
	for _, m := range regexp.MustCompile(`"([a-z_]+)"`).FindAllStringSubmatch(block[1], -1) {
		names = append(names, m[1])
	}
	if want := ProductionToolNames(protocol.BenchVersionV13); !reflect.DeepEqual(names, want) {
		t.Fatalf("screener _ORACLE_TOOL_NAMES drifted from CatalogForVersion(13):\n got %v\nwant %v\nregenerate with: go run ./cmd/catalogmirror -bench-version 13 -format python", names, want)
	}
}

func TestOpenClawPluginToolsMatchV13Surface(t *testing.T) {
	manifest := readMirror(t, "services/dittobench-api/integrations/openclaw/plugin/openclaw.plugin.json")
	var parsed struct {
		Contracts struct {
			Tools []string `json:"tools"`
		} `json:"contracts"`
	}
	if err := json.Unmarshal([]byte(manifest), &parsed); err != nil {
		t.Fatal(err)
	}
	want := ProductionToolNames(protocol.BenchVersionV13)
	if !reflect.DeepEqual(parsed.Contracts.Tools, want) {
		t.Fatalf("openclaw.plugin.json contracts.tools drifted:\n got %v\nwant %v", parsed.Contracts.Tools, want)
	}
	index := readMirror(t, "services/dittobench-api/integrations/openclaw/plugin/index.js")
	block := regexp.MustCompile(`(?s)const TOOL_NAMES = \[(.*?)\];`).FindStringSubmatch(index)
	if block == nil {
		t.Fatal("TOOL_NAMES block not found in index.js")
	}
	var names []string
	for _, m := range regexp.MustCompile(`"([a-z_]+)"`).FindAllStringSubmatch(block[1], -1) {
		names = append(names, m[1])
	}
	if !reflect.DeepEqual(names, want) {
		t.Fatalf("openclaw index.js TOOL_NAMES drifted:\n got %v\nwant %v", names, want)
	}
}
